<style scoped lang="scss">
.integration-marquee {
	width: 100%;
	padding: 0 0 8px;
	overflow: hidden;
	position: relative;
}

.marquee-section-label {
	text-align: center;
	font-size: 0.8rem;
	font-weight: 500;
	letter-spacing: 0.1em;
	text-transform: uppercase;
	color: var(--vp-c-text-3);
	margin: 0 0 20px;
}

.marquee-row {
	position: relative;
	overflow: hidden;
	margin-bottom: 12px;

	// Gradient fade edges
	&::before,
	&::after {
		content: '';
		position: absolute;
		top: 0;
		bottom: 0;
		width: 120px;
		z-index: 2;
		pointer-events: none;
	}

	&::before {
		left: 0;
		background: linear-gradient(to right, var(--vp-c-bg), transparent);
	}

	&::after {
		right: 0;
		background: linear-gradient(to left, var(--vp-c-bg), transparent);
	}
}

.marquee-track {
	display: flex;
	gap: 8px;
	width: max-content;
	will-change: transform;

	&--left {
		animation: marquee-scroll-left 65s linear infinite;
	}

	&--right {
		animation: marquee-scroll-right 65s linear infinite;
	}

	&:hover {
		animation-play-state: paused;
	}
}

@keyframes marquee-scroll-left {
	from { transform: translateX(0); }
	to   { transform: translateX(-50%); }
}

@keyframes marquee-scroll-right {
	from { transform: translateX(-50%); }
	to   { transform: translateX(0); }
}

.marquee-item {
	display: flex;
	align-items: center;
	gap: 8px;
	padding: 8px 16px;
	border-radius: 99px;
	background: var(--vp-c-bg-soft);
	border: 1px solid var(--vp-c-divider);
	white-space: nowrap;
	flex-shrink: 0;
	transition: border-color 0.2s, background 0.2s;
	cursor: default;

	&:hover {
		background: var(--vp-c-bg-mute);
	}
}

.marquee-icon {
	width: 20px;
	height: 20px;
	display: flex;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;

	svg {
		width: 20px;
		height: 20px;
	}
}

.marquee-text-icon {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 20px;
	height: 20px;
	border-radius: 4px;
	font-size: 0.6rem;
	font-weight: 700;
	letter-spacing: -0.02em;
	text-transform: uppercase;
}

.marquee-label {
	font-size: 0.82rem;
	font-weight: 500;
	color: var(--vp-c-text-2);
}

// ── Responsive ──────────────────────────────────────────────
@media (max-width: 768px) {
	.integration-marquee {
		padding: 28px 0 4px;
	}

	.marquee-section-label {
		font-size: 0.7rem;
		margin-bottom: 14px;
	}

	.marquee-row {
