			width: 16px;
			height: 16px;
		}
	}

	.marquee-text-icon {
		width: 16px;
		height: 16px;
		font-size: 0.5rem;
	}

	.marquee-label {
		font-size: 0.72rem;
	}
}

@media (max-width: 480px) {
	.marquee-row {
		&::before,
		&::after {
			width: 32px;
		}
	}

	.marquee-item {
		padding: 5px 8px;
		gap: 5px;
